-- V002: Milestone 2, Phase 1 core domain.
--
-- Organizations own projects; projects reference one GitHub repository; scans
-- are security analysis requests for one commit; scan jobs are the individual
-- scanner executions of a scan.
--
-- Conventions:
--   * UUID primary keys generated by the application (never by clients).
--   * All timestamps are TIMESTAMPTZ and written in UTC by the application.
--   * Aggregates reference each other by foreign key only. ON DELETE RESTRICT:
--     no cascading deletes of security history.
--   * CHECK constraints mirror the domain invariants enforced in Java, so a
--     defect or a manual write cannot persist an inconsistent security state.
--   * `version` supports optimistic locking.
--   * Constraint names: pk_/fk_/uq_/ck_/ix_<table>_<purpose>.

CREATE TABLE organizations (
    id         UUID         NOT NULL,
    name       VARCHAR(100) NOT NULL,
    slug       VARCHAR(63)  NOT NULL,
    version    BIGINT       NOT NULL,
    created_at TIMESTAMPTZ  NOT NULL,
    updated_at TIMESTAMPTZ  NOT NULL,
    CONSTRAINT pk_organizations PRIMARY KEY (id),
    CONSTRAINT uq_organizations_slug UNIQUE (slug),
    CONSTRAINT ck_organizations_name_not_blank CHECK (btrim(name) <> ''),
    CONSTRAINT ck_organizations_slug_format CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    CONSTRAINT ck_organizations_timestamps CHECK (updated_at >= created_at)
);

COMMENT ON TABLE organizations IS 'Tenants that own projects. Slug is the stable, unique, URL-safe identifier.';

CREATE TABLE projects (
    id                  UUID         NOT NULL,
    organization_id     UUID         NOT NULL,
    name                VARCHAR(100) NOT NULL,
    repository_provider VARCHAR(20)  NOT NULL,
    repository_owner    VARCHAR(39)  NOT NULL,
    repository_name     VARCHAR(100) NOT NULL,
    default_branch      VARCHAR(255) NOT NULL,
    enabled             BOOLEAN      NOT NULL,
    version             BIGINT       NOT NULL,
    created_at          TIMESTAMPTZ  NOT NULL,
    updated_at          TIMESTAMPTZ  NOT NULL,
    CONSTRAINT pk_projects PRIMARY KEY (id),
    CONSTRAINT fk_projects_organization FOREIGN KEY (organization_id)
        REFERENCES organizations (id) ON DELETE RESTRICT,
    -- Repository identity is stored normalized (lowercase), so this also
    -- rejects case-variant duplicates of the same GitHub repository.
    CONSTRAINT uq_projects_organization_repository
        UNIQUE (organization_id, repository_provider, repository_owner, repository_name),
    CONSTRAINT ck_projects_name_not_blank CHECK (btrim(name) <> ''),
    CONSTRAINT ck_projects_repository_provider CHECK (repository_provider IN ('GITHUB')),
    CONSTRAINT ck_projects_repository_owner_format
        CHECK (repository_owner ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    CONSTRAINT ck_projects_repository_name_format
        CHECK (repository_name ~ '^[a-z0-9._-]+$'
               AND repository_name NOT IN ('.', '..')
               AND repository_name NOT LIKE '%.git'),
    CONSTRAINT ck_projects_default_branch_not_blank CHECK (btrim(default_branch) <> ''),
    CONSTRAINT ck_projects_timestamps CHECK (updated_at >= created_at)
);

-- Supports the paginated per-organization listing (ordered by creation time).
CREATE INDEX ix_projects_organization_created ON projects (organization_id, created_at, id);

COMMENT ON TABLE projects IS 'Repositories registered for security scanning. No repository URL is stored or trusted.';

CREATE TABLE scans (
    id                  UUID         NOT NULL,
    project_id          UUID         NOT NULL,
    commit_sha          VARCHAR(64)  NOT NULL,
    branch              VARCHAR(255) NOT NULL,
    trigger_type        VARCHAR(20)  NOT NULL,
    execution_status    VARCHAR(20)  NOT NULL,
    security_decision   VARCHAR(20)  NOT NULL,
    idempotency_key     VARCHAR(128),
    request_fingerprint VARCHAR(64),
    version             BIGINT       NOT NULL,
    requested_at        TIMESTAMPTZ  NOT NULL,
    started_at          TIMESTAMPTZ,
    completed_at        TIMESTAMPTZ,
    updated_at          TIMESTAMPTZ  NOT NULL,
    CONSTRAINT pk_scans PRIMARY KEY (id),
    CONSTRAINT fk_scans_project FOREIGN KEY (project_id)
        REFERENCES projects (id) ON DELETE RESTRICT,
    -- Idempotency keys are scoped per project. NULL keys are distinct, so
    -- requests without a key always create a new scan.
    CONSTRAINT uq_scans_project_idempotency_key UNIQUE (project_id, idempotency_key),
    -- Full SHA-1 (40) or SHA-256 (64) object name, lowercase.
    CONSTRAINT ck_scans_commit_sha_format CHECK (commit_sha ~ '^[0-9a-f]{40}([0-9a-f]{24})?$'),
    CONSTRAINT ck_scans_branch_not_blank CHECK (btrim(branch) <> ''),
    CONSTRAINT ck_scans_trigger_type
        CHECK (trigger_type IN ('MANUAL', 'PUSH', 'PULL_REQUEST', 'SCHEDULED')),
    CONSTRAINT ck_scans_execution_status
        CHECK (execution_status IN ('QUEUED', 'RUNNING', 'COMPLETED', 'FAILED', 'CANCELLED')),
    CONSTRAINT ck_scans_security_decision
        CHECK (security_decision IN ('PENDING', 'PASS', 'FAIL', 'INCOMPLETE')),
    CONSTRAINT ck_scans_idempotency_pair
        CHECK ((idempotency_key IS NULL) = (request_fingerprint IS NULL)),
    CONSTRAINT ck_scans_request_fingerprint_format
        CHECK (request_fingerprint IS NULL OR request_fingerprint ~ '^[0-9a-f]{64}$'),
    -- Execution status and security decision are independent dimensions, but
    -- only these combinations are coherent. A scan that did not complete can
    -- never carry PASS or FAIL (fail closed), and a decision is only final
    -- once execution is terminal.
    CONSTRAINT ck_scans_status_decision CHECK (
        (execution_status IN ('QUEUED', 'RUNNING') AND security_decision = 'PENDING')
        OR (execution_status = 'COMPLETED' AND security_decision IN ('PASS', 'FAIL', 'INCOMPLETE'))
        OR (execution_status IN ('FAILED', 'CANCELLED') AND security_decision = 'INCOMPLETE')
    ),
    CONSTRAINT ck_scans_status_timestamps CHECK (
        (execution_status = 'QUEUED' AND started_at IS NULL AND completed_at IS NULL)
        OR (execution_status = 'RUNNING' AND started_at IS NOT NULL AND completed_at IS NULL)
        OR (execution_status = 'COMPLETED' AND started_at IS NOT NULL AND completed_at IS NOT NULL)
        OR (execution_status IN ('FAILED', 'CANCELLED') AND completed_at IS NOT NULL)
    ),
    CONSTRAINT ck_scans_timestamp_order CHECK (
        (started_at IS NULL OR started_at >= requested_at)
        AND (completed_at IS NULL OR completed_at >= COALESCE(started_at, requested_at))
        AND updated_at >= requested_at
    )
);

-- Supports the paginated per-project listing (newest first).
CREATE INDEX ix_scans_project_requested ON scans (project_id, requested_at DESC, id DESC);
CREATE INDEX ix_scans_project_commit ON scans (project_id, commit_sha);

COMMENT ON TABLE scans IS 'Security analysis requests. execution_status and security_decision are independent.';
COMMENT ON COLUMN scans.request_fingerprint IS 'SHA-256 of the normalized request; detects conflicting reuse of an idempotency key.';

CREATE TABLE scan_jobs (
    id               UUID        NOT NULL,
    scan_id          UUID        NOT NULL,
    scanner_type     VARCHAR(20) NOT NULL,
    execution_status VARCHAR(20) NOT NULL,
    attempt_count    INTEGER     NOT NULL,
    version          BIGINT      NOT NULL,
    created_at       TIMESTAMPTZ NOT NULL,
    started_at       TIMESTAMPTZ,
    completed_at     TIMESTAMPTZ,
    updated_at       TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_scan_jobs PRIMARY KEY (id),
    CONSTRAINT fk_scan_jobs_scan FOREIGN KEY (scan_id)
        REFERENCES scans (id) ON DELETE RESTRICT,
    CONSTRAINT uq_scan_jobs_scan_scanner UNIQUE (scan_id, scanner_type),
    CONSTRAINT ck_scan_jobs_scanner_type
        CHECK (scanner_type IN ('SEMGREP', 'GITLEAKS', 'TRIVY', 'CHECKOV', 'SYFT', 'ZAP')),
    CONSTRAINT ck_scan_jobs_execution_status
        CHECK (execution_status IN ('QUEUED', 'RUNNING', 'COMPLETED', 'FAILED', 'CANCELLED')),
    CONSTRAINT ck_scan_jobs_attempt_count CHECK (attempt_count BETWEEN 0 AND 3),
    CONSTRAINT ck_scan_jobs_status_timestamps CHECK (
        (execution_status = 'QUEUED' AND started_at IS NULL AND completed_at IS NULL)
        OR (execution_status = 'RUNNING' AND started_at IS NOT NULL AND completed_at IS NULL
            AND attempt_count >= 1)
        OR (execution_status = 'COMPLETED' AND started_at IS NOT NULL AND completed_at IS NOT NULL
            AND attempt_count >= 1)
        OR (execution_status IN ('FAILED', 'CANCELLED') AND completed_at IS NOT NULL)
    ),
    CONSTRAINT ck_scan_jobs_timestamp_order CHECK (
        (started_at IS NULL OR started_at >= created_at)
        AND (completed_at IS NULL OR completed_at >= COALESCE(started_at, created_at))
        AND updated_at >= created_at
    )
);

COMMENT ON TABLE scan_jobs IS 'One scanner execution within a scan. At most one job per scanner type per scan.';

INSERT INTO platform_metadata (metadata_key, metadata_value)
VALUES ('schema.core_domain', 'm2-phase1');
